cat > classic/apps/web/src/mcp/canonical-transport.ts <<'EOF'
import { z } from "zod";

/** These shapes describe the generic Rust protocol, never a feature/tool table. */
export const canonicalDescriptorSchema = z.object({
  id: z.string(), title: z.string(), description: z.string(), version: z.string(),
  inputSchema: z.record(z.string(), z.unknown()), outputSchema: z.record(z.string(), z.unknown()),
  access: z.enum(["read", "write", "destructive", "admin"]), idempotent: z.boolean(),
  openWorld: z.boolean(), transactional: z.boolean(), supportsDryRun: z.boolean(),
  cancellable: z.boolean(), available: z.boolean(), unavailableReason: z.string().nullable(),
  category: z.string(), tags: z.array(z.string()), documentSupport: z.string(), execution: z.string(),
});
export type CanonicalDescriptor = z.infer<typeof canonicalDescriptorSchema>;
export const canonicalRegistrySchema = z.object({ revision: z.number(), capabilities: z.array(canonicalDescriptorSchema) });
export const invocationOptionsSchema = z.object({
  dryRun: z.boolean().default(false), requestId: z.string().optional(),
  metadata: z.record(z.string(), z.unknown()).default({}),
}).strict();
export type CanonicalInvocationOptions = z.infer<typeof invocationOptionsSchema>;
export const artifactMetadataSchema = z.object({
  id: z.string(), uri: z.string().startsWith("opencut://artifacts/"), mimeType: z.string(),
  byteSize: z.number().int().nonnegative().max(16 * 1024 * 1024), sha256: z.string().regex(/^[a-f0-9]{64}$/),
  createdAtMs: z.number(), expiresAtMs: z.number(), width: z.number().nullable(),
  height: z.number().nullable(), durationMs: z.number().nullable(),
});
export const canonicalReceiptSchema = z.object({
  capabilityId: z.string(), capabilityVersion: z.string(), registryRevision: z.number(),
  result: z.object({data: z.unknown(), summary: z.string().nullable(), changedResources: z.array(z.string()), artifacts: z.array(artifactMetadataSchema).max(16)}),
});
export function advertiseCanonicalR

